        {
          "id": "tCcBQS2TNgo7EIvB",
          "name": "Efficient Capture",
          "kind": "action",
          "description": "Requirements Ilssrah has manacles in hand and is adjacent to a creature.\nEffect Ilssrah attempts to bind the creature's wrists or ankles with the manacles. If she succeeds at an attack roll with a check (efficient-capture, against:ac) modifier against the target's AC, she applies the manacles.",
          "traits": [
            "attack",
            "manipulate"
          ]
        },
        {
          "id": "n4acrtFiDu5TwYGe",
          "name": "Hammer the Chained",
          "kind": "action",
          "description": "Ilssrah attempts a melee Strike with Fleshroaster. If she hits, she also draws her light hammer, makes a melee Strike with it against the same target, and immediately returns it to her belt. She then resumes her grip on Fleshroaster. Both Strikes count toward Ilssrah's multiple attack penalty, but the penalty doesn't increase until both Strikes have been made. If the hammer Strike hits, it deals damage as normal and the target must attempt a check (fortitude, dc:35) save.\nCritical Success The creature is unaffected.\nSuccess The creature is Clumsy 1 and Stupefied 1 for 1 round.\nFailure The creature is clumsy 1 and stupefied 1 for 1 minute.\nCritical Failure The creature is Clumsy 2 and Stupefied 2 for 1 minute.",
          "traits": []
        }
