    "translatableHash": "sha256:f3adaeb39948dd4b8625d1c82d00652d4ba892f2100b2ce47ce5301e84498887",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Mental Scream Trap",
      "level": 19,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "magical",
        "trap"
      ],
      "description": "A psychic scream disorients creatures in the area.",
      "armorClass": 0,
      "hitPoints": 10,
      "hardness": 0,
      "stealth": {
        "modifier": 33,
        "details": "(master)"
      },
      "disable": "check (arcana, dc:41, name:Suppress the Magic, traits:magical,trap) to suppress the magic or check (thievery, dc:41, name:Scratch Out the Ward, traits:magical,trap) to scratch out the ward",
      "isComplex": false,
      "routine": "",
      "reset": "",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "LQ20lTeaoccMicH8",
          "name": "Psychic Screech",
          "kind": "reaction",
          "description": "Trigger A creature enters the marked area\nEffect A psychic wail affects all creatures within 10 feet of the marked area, requiring them to attempt a check (will, dc:41) save.\nCritical Success The target is unaffected.\nSuccess The target is Stunned 2.\nFailure The target is Paralyzed for 1 round, then stunned 2 when the paralysis ends.\nCritical Failure The target is paralyzed for 4 rounds. At the end of each of its turns, it can attempt a new Will save to reduce the remaining duration by 1 round, or end it entirely on a critical success.",
          "traits": [
            "arcane",
            "incapacitation",
            "mental"
          ]
        }
      ]
    },
