    "translatableHash": "sha256:1e1625de13d0cf5520214380468aee90b3c02484eb97f4af01dfae0db30b915b",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Dragonstorm",
      "level": 18,
      "rarity": "rare",
      "size": "medium",
      "traits": [
        "environmental",
        "magical"
      ],
      "description": "A massive storm stirs in the skies above Breachill and Citadel Altaerein. As specific events begin during the three waves of the manifestation's retribution, the dragonstorm wreaks localized havoc.",
      "armorClass": 0,
      "hitPoints": 10,
      "hardness": 0,
      "stealth": {
        "modifier": 40,
        "details": "(legendary)"
      },
      "disable": "The dragonstorm can't be disabled-only endured. It ends only once the attack on Breachill and Citadel Altaerein is over.",
      "isComplex": false,
      "routine": "",
      "reset": "",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "XzC7Tpe9v9HjnSor",
          "name": "Localized Dragonstorm",
          "kind": "reaction",
          "description": "Trigger A new wave begins\nEffect Roll 1d10 to determine which effect manifests from the following possibilities. The placement of these effects is guided by Dahak's will, and they should manifest in the most detrimental locations possible to the PCs.",
          "traits": [
            "air"
          ]
        },
        {
          "id": "0dYMOi8x5GT5a1Yq",
          "name": "1-2 Acid Rain",
          "kind": "passive",
          "description": "A torrent of acid drenches creatures in a 20-foot burst. Creatures in the area take 6d10 acid damage (check (reflex, dc:42, basic, options:area-effect) save). Creatures that critically fail also take 5 persistent acid damage.",
          "traits": [
            "acid"
          ]
        },
        {
          "id": "2tkYDAIULPFGgxZg",
          "name": "3-4 Freezing Wind",
          "kind": "passive",
          "description": "A barrage of freezing wind and hail assaults all creatures in a 20-foot burst. Creatures in the area take 3d10 cold damage damage (check (reflex, dc:42, basic, options:area-effect,inflicts:slowed) save). Creatures that critically fail are Slowed 1 for 1 round.",
          "traits": [
            "cold"
          ]
        },
        {
          "id": "tmioSSIeBsfcu9eY",
          "name": "5-6 Bolts of Lightning",
          "kind": "passive",
          "description": "Several bolts of lightning strike all creatures in a 20-foot burst. Creatures in the area take 6d10 electricity damage (check (reflex, dc:42, basic, options:area-effect,inflicts:blinded,inflicts:deafened) save). Creatures that critically fail their saves become Blinded and Deafened for 1 round.",
          "traits": [
            "electricity"
          ]
        },
        {
          "id": "xN7xuZd6V7GrLGii",
          "name": "7-8 Flaming Vortex",
          "kind": "passive",
          "description": "Gouts of flame fall on all creatures in a 20-foot burst. Creatures in the area take 6d10 fire damage (check (reflex, dc:42, basic, options:area-effect) save). Creatures that critically fail their saves also take 5 persistent fire damage.",
          "traits": [
            "fire"
          ]
        },
        {
          "id": "yRzCy4eBcJG8ydmJ",
          "name": "9-10 Poison Miasma",
          "kind": "passive",
          "description": "Poisonous mist rolls forth, covering a 20-foot burst for 1 round. Creatures within the mist become Concealed, and creatures outside it become concealed to creatures within it. Creatures within the mist take 6d10 poison damage (check (fortitude, dc:42, basic, options:area-effect,inflicts:enfeebled) save). Creatures that critically fail their saves become Enfeebled 2.",
          "traits": [
            "poison"
          ]
        }
      ]
    },
