      "actions": [
        {
          "id": "0vtEhVnugRtcZgdh",
          "name": "Attack of Opportunity (Special)",
          "kind": "reaction",
          "description": "Inizra can use Attack of Opportunity when a creature within her reach uses a concentrate action, in addition to its normal trigger. She can disrupt triggering concentrate actions, and she disrupts actions on any hit, not just a critical hit.",
          "traits": []
        },
        {
          "id": "0rU9AWHWD11ECFwB",
          "name": "Boundless Reprisals",
          "kind": "passive",
          "description": "Inizra gains a reaction at the start of each enemy's turn that she can use only during that turn.",
          "traits": []
        },
        {
          "id": "5SF4QUg5rtkR7Sy2",
          "name": "Mirror Shield",
          "kind": "reaction",
          "description": "Requirements You have a shield raised.\nTrigger An opponent casting a spell that targets you critically fails a spell attack roll against your AC.\nEffect You reflect the spell back against the triggering opponent. Make a ranged attack against the triggering creature using your highest proficiency with a ranged weapon. If you can cast spells, you can make a spell attack roll instead. If you succeed, your opponent takes the effects of a successful spell attack roll for their own spell (or the effects of a critical success if your attack roll was a critical success).",
          "traits": []
        },
        {
          "id": "ICOl05YuWjz7C6GN",
          "name": "Paragon's Guard Stance",
          "kind": "passive",
          "description": "Inizra always has her shield raised as if she had used the Raise a Shield action, as long as she meets that action's requirements.",
          "traits": []
        },
        {
          "id": "q1GTtW7ypFaAaLpl",
          "name": "Shield Block",
          "kind": "reaction",
          "description": "",
          "traits": []
        },
        {
          "id": "9A3DxTCqkhPOFzSd",
          "name": "Weapon Supremacy",
          "kind": "passive",
          "description": "Inizra is permanently Quickened. She can use her extra action only to Strike.",
          "traits": []
        }
      ],
      "spellcasting": []
