    "data": {
      "schemaVersion": 1,
      "name": "Vazgorlu",
      "level": 20,
      "rarity": "rare",
      "size": "large",
      "traits": [
        "aberration",
        "astral",
        "evil"
      ],
      "description": "The arthropod monstrosity known as a vazgorlu makes its home on the Astral Plane or inside of a stable portal, ambushing creatures that travel there using dimensional magic.",
      "armorClass": 45,
      "hitPoints": 380,
      "speedFeet": 30,
      "perception": {
        "modifier": 33,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 30,
        "reflex": 33,
        "will": 36
      },
      "abilities": {
        "str": 6,
        "dex": 7,
        "con": 6,
        "int": 7,
        "wis": 8,
        "cha": 5
      },
      "skills": {
        "arcana": 38,
        "deception": 38,
        "stealth": 34,
        "thievery": 32
      },
      "languages": [
        "aklo",
        "chthonian",
        "daemonic",
        "diabolic",
        "empyrean",
        "protean",
        "requian",
        "utopian"
      ],
      "defenses": {
        "immunities": [
          "acid",
          "paralyzed",
          "sleep"
        ],
        "resistances": [
          "cold 15",
          "physical 10 except cold-iron"
        ],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "ppTxZD2ni4N12liM",
          "name": "Fangs",
          "bonus": 38,
          "damage": "4d10+8 piercing; 3d10 acid",
          "traits": [
            "reach-10"
          ]
        },
        {
          "id": "e7C7CLUio6dT7UwM",
          "name": "Web",
          "bonus": 38,
          "damage": "6d6+8 acid",
          "traits": []
        }
      ],
      "actions": [
        {
          "id": "yfiUAGMbYu5GpkVc",
          "name": "Constant Spells",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "MNIeEFHVbRZ8b5Ln",
          "name": "Hostile Juxtaposition",
          "kind": "reaction",
          "description": "Trigger A creature targets the vazgorlu with a Strike\nEffect The vazgorlu chooses a different creature within 60 feet and attempts to swap places with that creature using Translocate in the instant before the Strike. The target must attempt a check (will, dc:39, traits:arcana) save.\nCritical Success The target resists the teleportation, and the vazgorlu can't use Hostile Juxtaposition for 1d4.\nSuccess The target resists the teleportation.\nFailure The target and the vazgorlu instantly swap places, and the triggering Strike is resolved against the target instead.\nCritical Failure As failure, but the target is transported to the vazgorlu's demiplane after resolving the triggering Strike against it.",
          "traits": [
            "arcane",
            "teleportation"
          ]
        },
        {
          "id": "MTe5oaN8qxo4KYFm",
          "name": "Demiplane Lair",
          "kind": "passive",
          "description": "A vazgorlu maintains a 30-foot-diameter demiplane in the Astral Plane. Gravity in this demiplane pulls out from the center, so that creatures can walk upon the inner surface. A vazgorlu's demiplane lair lacks a built-in point of exit, and if the vazgorlu fails to visit the demiplane during a 24-hour period, the demiplane collapses- all objects and creatures within are then returned to their original locations in the multiverse before they entered the demiplane. A vazgorlu can create a replacement demiplane lair with 24 hours of concentration.",
          "traits": []
        },
        {
          "id": "jwRUzgElIiQUtmhR",
          "name": "Dimensional Tether",
          "kind": "passive",
          "description": "A creature hit by a vazgorlu's web Strike is Immobilized and stuck to the nearest surface until it Escape DC 42. As long as it remains immobilized by the web, the web attempts to counteract any effect that would move the webbed creature to another plane, with a counteract rank of 10 and using the vazgorlu's 1d20+38 skill to attempt the counteract check.",
          "traits": []
        },
        {
          "id": "Z875mlZme0MfKkqS",
          "name": "Redirect Portal",
          "kind": "passive",
          "description": "A vazgorlu can spend 10 minutes in contact with a magical portal to redirect it, causing the portal to instead lead to its demiplane lair. To do so, the vazgorlu must succeed at a 1d20+41 check (the DC is either equal to the caster's spell DC for a portal created by a spell, or set by the portal's level; if the portal in question has no level listed, assume it's a 20th-level portal).",
          "traits": []
        }
      ],
      "spellcasting": [
        {
          "id": "rqq8NjCeDPoInPTq",
          "name": "Arcane Innate Spells",
          "tradition": "arcane",
          "category": "innate",
          "attackModifier": 27,
          "saveDc": 35,
          "spells": [
            {
              "id": "CNMsxGsJc8C2klMn",
              "name": "Air Walk (Constant)",
              "rank": 4
            },
            {
              "id": "OMliTjyRbQBsIAzC",
              "name": "Dimension Door (At Will)",
              "rank": 4
            },
            {
              "id": "j9OR4GAOwpFolkP9",
              "name": "Plane Shift (To and From the Vazgorlu's Demiplane Only)",
              "rank": 7
            },
            {
              "id": "Tx7ziW7v0FU1vsah",
              "name": "Teleport",
              "rank": 7
            }
          ]
        }
      ]
    },
