        {
          "id": "KrTgWTUW9uB20sKT",
          "name": "Frightful Presence",
          "kind": "passive",
          "description": "90 feet. check (will, dc:42, options:area-effect,inflicts:frightened)",
          "traits": [
            "aura",
            "emotion",
            "fear",
            "mental"
          ]
        },
        {
          "id": "6m1q9eJjaPr21j44",
          "name": "Redirect Energy",
          "kind": "reaction",
          "description": "Trigger A creature within 100 feet casts an acid, cold, fire, electricity, or poison spell, or such a spell otherwise comes into effect from a source within 100 feet\nEffect The manifestation of Dahak makes all the choices to determine the targets, destination, or other effects of the spell, as though it were the caster.",
          "traits": [
            "divine"
          ]
        },
        {
          "id": "kyJU0dp0AuLccYHV",
          "name": "Breath Weapon",
          "kind": "action",
          "description": "The manifestation of Dahak breathes a blast of dragonstorm energy that deals 5d6 acid damage,5d6 electricity damage,5d6 fire damage,5d6 poison damage in a 60-foot cone (check (reflex, dc:46, basic, name:Dragonstorm Breath, traits:fire,acid,cold,electricity,poison, options:area-effect) save).\nIt can't use Dragonstorm Breath again for 1d4.",
          "traits": [
            "divine"
          ]
        },
        {
          "id": "kJz2LXDyAG4vASIf",
          "name": "Draconic Frenzy",
          "kind": "action",
          "description": "The dragon makes two claw Strikes and one wing Strike in any order.",
          "traits": []
        },
        {
          "id": "ppHf9s7R9QhMXyxE",
          "name": "Draconic Momentum",
          "kind": "passive",
          "description": "The dragon recharges its Breath Weapon whenever it scores a critical hit with a Strike.",
          "traits": []
        },
        {
          "id": "HEnPvo9LJho9qb75",
          "name": "Manipulate Energy",
          "kind": "action",
          "description": "The manifestation attempts to take control of a magical acid, cold, electricity, fire, or poison spell within 100 feet. If it succeeds at a counteract check (counteract rank 10, counteract modifier 1d20+36), the original caster loses control of the spell, control is transferred to the manifestation, and the manifestation counts as having Sustained the Spell with this action (if applicable). The manifestation can end the spell instead of taking control, if it chooses.",
          "traits": [
            "concentrate",
            "divine"
          ]
        }
