    "data": {
      "schemaVersion": 1,
      "name": "Smiler",
      "level": 2,
      "rarity": "unique",
      "size": "medium",
      "traits": [
        "chaotic",
        "evil",
        "ghoul",
        "undead",
        "unholy"
      ],
      "description": "Ghasts-feral, foul-smelling, and constantly hungry-are the more powerful kin of ghouls. They are relentless in the pursuit of their prey.\nFew creatures are more ubiquitous to sinister locations such as lonely graveyards and ruined crypts than the flesh-eating undead known as ghouls.",
      "armorClass": 19,
      "hitPoints": 45,
      "speedFeet": 30,
      "perception": {
        "modifier": 12,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 9,
        "reflex": 12,
        "will": 8
      },
      "abilities": {
        "str": 3,
        "dex": 4,
        "con": 2,
        "int": 1,
        "wis": 2,
        "cha": 4
      },
      "skills": {
        "acrobatics": 9,
        "athletics": 9,
        "intimidation": 9,
        "stealth": 9
      },
      "languages": [
        "common",
        "necril"
      ],
      "defenses": {
        "immunities": [
          "bleed",
          "death-effects",
          "disease",
          "paralyzed",
          "poison",
          "unconscious"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "phoQ0yOkbf9saI2l",
          "name": "Jaws",
          "bonus": 12,
          "damage": "2d6+4 piercing",
          "traits": [
            "finesse",
            "unarmed"
          ]
        },
        {
          "id": "OcYo8NrM7fSjcymh",
          "name": "Claw",
          "bonus": 12,
          "damage": "2d4+4 slashing",
          "traits": [
            "agile",
            "finesse",
            "unarmed"
          ]
        },
        {
          "id": "U4mx6nAal2UDRgr5",
          "name": "Shortbow",
          "bonus": 12,
          "damage": "1d6+4 piercing",
          "traits": [
            "deadly-d10",
            "propulsive",
            "reload-0"
          ]
        }
      ],
      "actions": [
        {
          "id": "xdZGT2FQbkaAnnVv",
          "name": "Stench",
          "kind": "passive",
          "description": "10 feet. A creature entering the aura or starting its turn in the aura must succeed at a check (fortitude, dc:18, options:area-effect,inflicts:sickened,inflicts:slowed) save or become Sickened 1 (plus Slowed 1 as long as it's sickened on a critical failure).\nWhile within the aura, the creature takes a -2 circumstance penalty to saves against disease and to recover from the sickened condition. A creature that succeeds at its save is temporarily immune for 1 minute.\nEffect: Ghast Stench",
          "traits": [
            "aura",
            "olfactory"
          ]
        },
        {
          "id": "mJ6Xt01ZdOkIrWw2",
          "name": "Void Healing",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "AUdWGOamBXZXat3B",
          "name": "Consume Flesh",
          "kind": "action",
          "description": "Requirements Smiler is adjacent to the corpse of a creature that died within the last hour.\nEffect Smiler devours a chunk of the corpse and regains 3d6 healing Hit Points.\nHe can regain Hit Points from any given corpse only once.",
          "traits": [
            "manipulate"
          ]
        },
        {
          "id": "GCpCG2QeVwHXzzqM",
          "name": "Ghast Fever",
          "kind": "passive",
          "description": "Saving Throw check (fortitude, dc:18)\nStage 1 carrier with no ill effect (1 day)\nStage 2 3d8 void damage and regains half as many Hit Points from all healing (1 day)\nStage 3 as stage 2 (1 day)\nStage 4 3d8 void damage and gains no benefit from healing (1 day)\nStage 5 as stage 4 (1 day)\nStage 6 dead, and rises as a Ghast the next midnight",
          "traits": [
            "disease"
          ]
        },
        {
          "id": "ce0ME84C2cbPH0JA",
          "name": "Paralysis",
          "kind": "passive",
          "description": "Any living creature hit by Smiler's attack must succeed at a check (fortitude, dc:18, options:inflicts:paralyzed) save or become Paralyzed. It can attempt a new save at the end of each of its turns, and the DC cumulatively decreases by 1 on each such save.",
          "traits": [
            "incapacitation",
            "occult"
          ]
        },
        {
          "id": "k1Ehx0dobB1JSYjA",
          "name": "Swift Leap",
          "kind": "action",
          "description": "Smiler jumps up to half his Speed. This movement doesn't trigger reactions.",
          "traits": [
            "move"
          ]
        }
      ],
      "spellcasting": []
    },
