    "sourceHash": "sha256:7bd38beeb37c087659883b59eeb2e1619f0747a8fb399d09b1fbd65991bb1972",
    "translatableHash": "sha256:c57ba8f69110731360a34e71db35e5c66f553887fce55432511a952eff7a3875",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Dream Pollen Pod",
      "level": 3,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "environmental",
        "trap"
      ],
      "description": "Four magical plants inside the wagon release hallucinogenic pollen when disturbed.",
      "armorClass": 18,
      "hitPoints": 32,
      "hardness": 1,
      "stealth": {
        "modifier": 12,
        "details": "(trained)"
      },
      "disable": "check (thievery, dc:18, name:Remove Pollen Pod) (trained) to carefully remove a pollen pod or check (nature, dc:18, name:Prevent Pod Burst) (trained) to prevent a pod from bursting.",
      "isComplex": true,
      "routine": "(4 actions) The trap loses 1 action each turn for each removed or disabled pollen pod. The trap doesn't take a multiple attack penalty.",
      "reset": "The trap resets after 1 hour, when the pods have regrown additional pollen. If all the pods are removed or disabled, the trap doesn't reset.",
      "saves": {
        "fortitude": 9,
        "reflex": 3,
        "will": 0
      },
      "defenses": {
        "immunities": [
          "critical-hits",
          "precision"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "ead7pwbvr3oideQg",
          "name": "Pollen Burst",
          "kind": "reaction",
          "description": "Trigger The wagon door is opened or the pods are disturbed\nEffect A pod makes a pollen spray Strike against an adjacent creature or the creature that opened the door, the door falls off the wagon, and the trap rolls initiative.",
          "traits": []
        },
        {
          "id": "oxKLVBMpW1qrYgZH",
          "name": "Hallucinogenic Pollen",
          "kind": "passive",
          "description": "A creature hit by the trap's pollen spray must succeed at a check (will, dc:20) save or it is Confused for 1 round and takes a -2 status penalty to Perception checks and saves against mental effects for 1d4 hours. On a critical failure, the penalty is instead -4.\nEffect: Hallucinogenic Pollen (Failure)\nEffect: Hallucinogenic Pollen (Critical Failure)",
          "traits": []
        }
      ]
    },
