    "translatableHash": "sha256:89e7482ada85281112feeb0df193bbe38ca4d78ebb0d94eb76fbc05cf46ad2e0",
    "data": {
      "schemaVersion": 1,
      "name": "Flea Swarm",
      "level": 5,
      "rarity": "common",
      "size": "large",
      "traits": [
        "animal",
        "swarm"
      ],
      "description": "Flea swarms roil across city streets and rural hinterlands in a hissing, scraping scrabble, draining blood from any creatures unfortunate enough to cross their path.\nFleas are little more than a nuisance in most circumstances, but can be lethal when they grow to monstrous proportions or gather in enormous swarms.",
      "armorClass": 18,
      "hitPoints": 55,
      "speedFeet": 30,
      "perception": {
        "modifier": 13,
        "senses": [
          "low-light-vision",
          "scent-imprecise-30"
        ]
      },
      "saves": {
        "fortitude": 15,
        "reflex": 16,
        "will": 6
      },
      "abilities": {
        "str": -2,
        "dex": 5,
        "con": 4,
        "int": -5,
        "wis": 1,
        "cha": -4
      },
      "skills": {
        "acrobatics": 14,
        "athletics": 9
      },
      "languages": [],
      "defenses": {
        "immunities": [
          "disease",
          "precision",
          "swarm-mind"
        ],
        "resistances": [
          "physical 8 except bludgeoning"
        ],
        "weaknesses": [
          "area-damage 4",
          "splash-damage 4"
        ]
      },
      "attacks": [],
      "actions": [
        {
          "id": "coep2DirH6k49uz3",
          "name": "Flea Fever",
          "kind": "passive",
          "description": "Drain from flea fever can't be reduced or recovered from naturally until the disease is cured.\nSaving Throw check (fortitude, dc:19)\nStage 1 Drained 1 (1d4)\nStage 2 drained 1 and Sickened 1 (1 day)\nStage 3 Drained 2 and sickened 1 (1 day)\nStage 4 Drained 3 and sickened 1 (1 day)\nStage 5 dead",
          "traits": [
            "disease"
          ]
        },
        {
          "id": "O3GuY1OWhHhmq9FW",
          "name": "Suck Blood",
          "kind": "action",
          "description": "Requirements The flea swarm's last action was Swarming Bites, and it dealt damage to at least one enemy\nEffect The flea swarm drinks the creatures' blood. Each victim becomes Drained 1 and the swarm regains 3 healing HP for each victim drained.",
          "traits": []
        },
        {
          "id": "ZmpXD5Zs0PQBXPU3",
          "name": "Swarming Bites",
          "kind": "action",
          "description": "Each enemy in the swarm's space takes 2d4+7 piercing damage and must attempt a check (reflex, dc:22, basic, options:area-effect) save. A creature that fails its save is exposed to flea fever.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
