    "translatableHash": "sha256:dfd32eecade51377fa48a1aacb5cc7b1eec741bcd58f6071a00a9d605b01fd85",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Thunderstone Cascade Trap",
      "level": 7,
      "rarity": "uncommon",
      "size": "medium",
      "traits": [
        "mechanical",
        "trap"
      ],
      "description": "A trip wire halfway up the stairs releases half a dozen spherical thunderstones that bounce down the stairs and explode.",
      "armorClass": 26,
      "hitPoints": 54,
      "hardness": 0,
      "stealth": {
        "modifier": 15,
        "details": "(expert)"
      },
      "disable": "check (thievery, dc:27, name:Safely Cut the Trip Wire, traits:mechanical,hazard,trap) (expert) to safely cut the trip wire",
      "isComplex": false,
      "routine": "",
      "reset": "",
      "saves": {
        "fortitude": 15,
        "reflex": 13,
        "will": 0
      },
      "defenses": {
        "immunities": [
          "critical-hits",
          "precision"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "JTK8CW0TwOok1X9Z",
          "name": "Thunderstone Explosion",
          "kind": "reaction",
          "description": "Trigger The trip wire is disturbed\nEffect Several thunderstones bounce down the stairs and explode. Each creature within 10 feet of the lower half of the stairs takes 6d10 sonic damage (check (fortitude, dc:24, basic, traits:hazard,trap,mechanical) save). Creatures that fail this save are additionally Deafened for 1 minute; creatures that critically fail this save are instead deafened for 1 hour.",
          "traits": []
        }
      ]
    },
