    "data": {
      "schemaVersion": 1,
      "name": "Evora Yarket",
      "level": 7,
      "rarity": "unique",
      "size": "medium",
      "traits": [
        "human",
        "humanoid",
        "orc"
      ],
      "description": "",
      "armorClass": 22,
      "hitPoints": 115,
      "speedFeet": 35,
      "perception": {
        "modifier": 14,
        "senses": [
          "low-light-vision"
        ]
      },
      "saves": {
        "fortitude": 16,
        "reflex": 11,
        "will": 13
      },
      "abilities": {
        "str": 5,
        "dex": 0,
        "con": 3,
        "int": 1,
        "wis": 2,
        "cha": -1
      },
      "skills": {
        "acrobatics": 11,
        "athletics": 19,
        "intimidation": 10,
        "nature": 13,
        "performance": 10,
        "survival": 13
      },
      "languages": [
        "common",
        "hallit",
        "orcish"
      ],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "8pEUtQIaEuhNMeNq",
          "name": "Falling Stone Unarmed Attack",
          "bonus": 18,
          "damage": "2d8+6 bludgeoning",
          "traits": [
            "forceful",
            "nonlethal",
            "unarmed"
          ]
        }
      ],
      "actions": [
        {
          "id": "QR5bODSKMiojeESn",
          "name": "Orc Ferocity",
          "kind": "reaction",
          "description": "Frequency once per day\nTrigger Evora would be reduced to 0 Hit Points but not immediately killed\nEffect Evora avoids being knocked out and remains at 1 Hit Point, and her Wounded condition increases by 1.",
          "traits": []
        },
        {
          "id": "JBZGDHmgcSKsrjtc",
          "name": "Stand Still",
          "kind": "reaction",
          "description": "Trigger A creature within Evora's reach uses a move action or leaves a square during a move action it's using\nEffect Evora makes a melee Strike against the triggering creature. If this attack is a critical hit and the trigger was a move action, she disrupts that action.",
          "traits": []
        },
        {
          "id": "Cgn2V1u3dIaaSjCc",
          "name": "Successful Fortitude saves are critical successes instead",
          "kind": "passive",
          "description": "Successful Fortitude saves are critical successes instead",
          "traits": []
        },
        {
          "id": "mXs0X782H3FV7qJD",
          "name": "Flurry of Blows",
          "kind": "action",
          "description": "Effect Evora makes two unarmed Strikes. If both hit the same creature, combine their damage and apply resistances and weaknesses only once. She applies her multiple attack penalty to the Strikes normally.\nAs it has the flourish trait, Evora can use Flurry of Blows only once per turn.",
          "traits": [
            "flourish"
          ]
        },
        {
          "id": "QhKOuFQANuodhk8x",
          "name": "Mountain Stance",
          "kind": "action",
          "description": "Requirements Evora is unarmored and touching the ground\nEffect Evora enters the stance of an implacable mountain until she is knocked out or the encounter ends. She gains a +4 status bonus to AC and a +2 circumstance bonus to any defenses against being Shoved or Tripped. Her Speed is reduced by 5 feet.",
          "traits": [
            "stance"
          ]
        },
        {
          "id": "q0Go6gYxsqhxoIiT",
          "name": "Mountain Stronghold",
          "kind": "action",
          "description": "Requirements Evora is in Mountain Stance\nEffect Evora gains a +2 circumstance bonus to AC until the beginning of her next turn.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
