    "sourceHash": "sha256:102aa9a78bff098546e80908a7a835eb7b973d6086c00d40f720415f17d3eb07",
    "translatableHash": "sha256:50e8ab470f14414ae947e605b77aca4ee11a0eae4f099b55b8a407e5e5552d9b",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Krooth Summoning Rune",
      "level": 8,
      "rarity": "uncommon",
      "size": "medium",
      "traits": [
        "magical",
        "trap"
      ],
      "description": "The haze conceals a rune that summons a krooth in front of the door to area B10.",
      "armorClass": 0,
      "hitPoints": 10,
      "hardness": 0,
      "stealth": {
        "modifier": 14,
        "details": "(expert)"
      },
      "disable": "check (acrobatics, dc:24, name:Approach without triggering the trap, traits:hazard,complex,magical,trap) to approach without triggering the trap followed by check (thievery, dc:26, name:Erase the rune, traits:hazard,complex,magical,trap) (expert) to erase the rune, or Dispel Magic (4th rank; counteract DC 24) to counteract the rune.",
      "isComplex": true,
      "routine": "",
      "reset": "The trap resets after 24 hours.",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "zBa9WIu0MHIhcZTg",
          "name": "Summon Monster",
          "kind": "reaction",
          "description": "Trigger A non-xulgath, non-demon creature that isn't carrying a religious symbol of Zevgavizeb crosses from the north part of the hall to the south part of the hall\nEffect The trap summons a Krooth. The krooth rolls initiative and remains for 2d6, after which the spell ends and the krooth disappears. The krooth also disappears if someone disables the trap before the duration expires. Unlike most summoned creatures, the krooth can use 3 actions each round and can use reactions.",
          "traits": [
            "arcane",
            "summon"
          ]
        }
      ]
    },
