    "sourceHash": "sha256:bf62a52b48ada8d12123a9f02f318c12fd10dc0586c4c8009d1cb5c5c430ea57",
    "translatableHash": "sha256:6d5caeed294a98eb7488a975d54fc64b909f7ea517aa64ea3dbb9e7b664a3c11",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Ghost Crystal Cloud",
      "level": 8,
      "rarity": "uncommon",
      "size": "medium",
      "traits": [
        "environmental"
      ],
      "description": "The xulgath corpse splits open to release a cloud of tiny ectoplasmic crystals which, when they are inhaled, disorient and devitalize living creatures.",
      "armorClass": 27,
      "hitPoints": 70,
      "hardness": 0,
      "stealth": {
        "modifier": 18,
        "details": "(trained)"
      },
      "disable": "check (arcana, dc:26, name:Render the cloud inert, traits:hazard,environmental) or check (occultism, dc:26, name:Render the cloud inert, traits:hazard,environmental) (expert) to render the crystal cloud inert",
      "isComplex": false,
      "routine": "",
      "reset": "The crystals regrow into a number sufficient to form another dangerous cloud after 1 week.",
      "saves": {
        "fortitude": 17,
        "reflex": 13,
        "will": 0
      },
      "defenses": {
        "immunities": [
          "critical-hits",
          "precision"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "zDJDO6RiYek1vtDZ",
          "name": "Ectoplasmic Explosion",
          "kind": "reaction",
          "description": "Trigger A creature touches or disturbs the corpse containing the growth of crystals\nEffect All creatures within 10 feet of the corpse are exposed to the ghost crystal cloud.",
          "traits": []
        },
        {
          "id": "NrFxf3psvDqHyWQv",
          "name": "Ghost Crystal Cloud",
          "kind": "passive",
          "description": "Creatures with the ethereal trait are immune\nSaving Throw check (fortitude, dc:26, traits:environmental,hazard)\nMaximum Duration 6 rounds\nStage 1 1d10 poison damage and Stupefied 1 (1 round)\nStage 2 2d10 poison damage and Stupefied 2 (1 round)\nStage 3 3d10 poison damage and Stupefied 3 (1 round)",
          "traits": [
            "poison"
          ]
        }
      ]
    },
