      "actions": [
        {
          "id": "PTFpKWM9gdLACL3N",
          "name": "Coven",
          "kind": "passive",
          "description": "Skarja adds Dominate, Nightmare, Scrying, and Spellwrack to her coven's spells.",
          "traits": [
            "mental",
            "occult"
          ]
        },
        {
          "id": "UOVIQWXoyaOc2IBj",
          "name": "Nightmare Rider",
          "kind": "passive",
          "description": "When Skarja rides a Nightmare, the nightmare also gains her status bonus to saves against magic, and both the hag and rider benefit when Skarja uses her Heartstone's Ethereal Jaunt innate spell.",
          "traits": []
        },
        {
          "id": "2UrfKw5PocQe3AE6",
          "name": "Constant Spells",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "UwmfxnwjIDn1MR7C",
          "name": "+2 Status to All Saves vs. Magic",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "YRWhIzukE4zO9fUH",
          "name": "-2 to All Saves (If Hearstone is Lost)",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "I8280Iq9dO7AtDc4",
          "name": "Abyssal Plague",
          "kind": "passive",
          "description": "A creature can't recover from the Drained condition until Abyssal plague is cured\nSaving Throw check (fortitude, dc:33)\nStage 1 Drained 1 (1 day)\nStage 2 drained increases by 2 (1 day)",
          "traits": [
            "disease"
          ]
        },
        {
          "id": "Y7eL4NGth0AzOHCF",
          "name": "Change Shape",
          "kind": "action",
          "description": "Skarja can take on the appearance of any Medium female humanoid. This doesn't change her Speed or her attack or damage bonuses with her Strikes, but might change the damage type her Strikes deal (typically to bludgeoning).",
          "traits": [
            "concentrate",
            "occult",
            "polymorph"
          ]
        },
        {
          "id": "tW1DUMQeCYYiJFWi",
          "name": "Dream Haunting",
          "kind": "passive",
          "description": "If Skarja is ethereal and hovering over a sleeping chaotic or evil creature, she can ride the victim's back until dawn. The creature endures tormenting dreams as Skarja casts Nightmare on it, and is exposed to Abyssal Plague.\nAny Drained condition caused by dream haunting is cumulative. Only an ethereal being can confront the night hag and stop her dream haunting.",
          "traits": [
            "mental",
            "occult"
          ]
        },
        {
          "id": "YOtRTnyprnEC769l",
          "name": "Spell Ambush",
          "kind": "passive",
          "description": "A creature Off-Guard to the night hag takes a -2 circumstance penalty to checks and DCs to defend against her spells.",
          "traits": []
        }
      ],
