    "sourceHash": "sha256:9f1b58c5706069f54c5be38045068376fdd0c36285d4a48e922d160f2f6578ff",
    "translatableHash": "sha256:c75131bdfc0a9fd1fcaf27c1a4cf29cf85b975c3d0576396c21fa34dba03b610",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Mukradi Summoning Runes",
      "level": 15,
      "rarity": "uncommon",
      "size": "medium",
      "traits": [
        "magical",
        "trap"
      ],
      "description": "Barely visible runes are etched into the stone floor in a 20-foot diameter circle.",
      "armorClass": 0,
      "hitPoints": 10,
      "hardness": 0,
      "stealth": {
        "modifier": 25,
        "details": "(master) to notice runes marked on the floor."
      },
      "disable": "check (acrobatics, dc:36, name:Approach Rune) to approach without triggering the trap followed by check (occultism, dc:34, name:Erase the Rune) (expert) or check (thievery, dc:38, name:Erase the Rune, traits:action:disable-a-device) (master) to erase the rune, or Dispel Magic (8th rank; counteract DC 34) to counteract the rune.",
      "isComplex": true,
      "routine": "",
      "reset": "The trap resets at the first high tide of each day.",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "6jthkAwvS3DHh7jF",
          "name": "Summon Monster",
          "kind": "reaction",
          "description": "Trigger A creature enters the circle without uttering the passphrase, \"Praise to the Water Lizard\"\nEffect The trap summons a Mukradi. The mukradi rolls initiative and remains for 1 minute, after which the spell ends and the mukradi disappears. The mukradi also disappears if someone disables the trap before the duration expires. The mukradi can use 3 actions each round and can use reactions, unlike most summoned creatures.",
          "traits": [
            "occult",
            "summon"
          ]
        }
      ]
    },
