    "data": {
      "schemaVersion": 1,
      "name": "Urdefhan Hunter",
      "level": 12,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "evil",
        "humanoid",
        "urdefhan"
      ],
      "description": "Urdefhan hunters serve as their cults' trappers, hunters, and poachers. Many urdefhan hunters use skavelings to traverse the massive caverns of the Darklands and scout for prey.\nUrdefhans believe themselves to be spawn of the First Horseman of the Apocalypse, who planted them on the Material Plane to serve as harbingers of the end times. These warmongering humanoids live in groups called cults in the Darklands vaults of Orv.",
      "armorClass": 34,
      "hitPoints": 190,
      "speedFeet": 30,
      "perception": {
        "modifier": 26,
        "senses": [
          "greater-darkvision"
        ]
      },
      "saves": {
        "fortitude": 20,
        "reflex": 26,
        "will": 23
      },
      "abilities": {
        "str": 4,
        "dex": 6,
        "con": 4,
        "int": 2,
        "wis": 5,
        "cha": 1
      },
      "skills": {
        "acrobatics": 24,
        "nature": 23,
        "religion": 21,
        "stealth": 26,
        "survival": 25
      },
      "languages": [
        "aklo",
        "daemonic",
        "sakvroth"
      ],
      "defenses": {
        "immunities": [
          "disease",
          "fear-effects"
        ],
        "resistances": [],
        "weaknesses": [
          "vitality 12"
        ]
      },
      "attacks": [
        {
          "id": "jwtvc92eNGbKi3wr",
          "name": "Rhoka Sword",
          "bonus": 24,
          "damage": "2d8+10 slashing",
          "traits": [
            "fatal-d10",
            "magical",
            "two-hand-d12"
          ]
        },
        {
          "id": "LHyFqz22wgaucwGA",
          "name": "Jaws",
          "bonus": 22,
          "damage": "3d6+10 piercing",
          "traits": [
            "agile",
            "unarmed"
          ]
        },
        {
          "id": "ZAxGEizKqPqUvP2N",
          "name": "Composite Longbow",
          "bonus": 26,
          "damage": "2d8+4 piercing",
          "traits": [
            "deadly-d10",
            "magical",
            "propulsive",
            "reload-0",
            "volley-30"
          ]
        }
      ],
      "actions": [
        {
          "id": "fzEhis5mum8aBN0a",
          "name": "Greater Darkvision",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "2mOCKRrDP2pm8VSK",
          "name": "Necrotic Decay",
          "kind": "passive",
          "description": "When an urdefhan dies, its invisible flesh quickly rots away and sublimates into a foul-smelling gas that fills a 5-foot emanation around the body.\nThis gas deals 12d6 void damage to creatures in this area as their flesh curdles and rots as well (check (fortitude, dc:32, basic, options:area-effect) save).",
          "traits": [
            "divine",
            "void"
          ]
        },
        {
          "id": "DsnYPhbnCJOnQiIV",
          "name": "Void Healing",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "gnbyS4J4UvV5J0pq",
          "name": "Deadly Aim",
          "kind": "action",
          "description": "The urdefhan hunter makes a ranged Strike at a –2 penalty. The urdefhan deals 4 additional damage with this Strike.",
          "traits": []
        },
        {
          "id": "1W3SqzQpvwlpRf5W",
          "name": "Double Shot",
          "kind": "action",
          "description": "Requirements The urdefhan hunter is wielding a ranged weapon with reload 0\nEffect The urdefhan hunter makes two Strikes with the required weapon at a single target. These Strikes both count toward the urdefhan's multiple attack penalty, but the penalty doesn't increase until both attacks are resolved.",
          "traits": []
        },
        {
          "id": "Ba3OUInVSq7YCdrO",
          "name": "Mounted Bow Expert",
          "kind": "passive",
          "description": "Urdefhan hunters can make composite longbow Strikes while mounted.",
          "traits": []
        },
        {
          "id": "AKIZnRoLY7lsf9VG",
          "name": "Wicked Bite",
          "kind": "action",
          "description": "Requirements The urdefhan damaged a creature with a jaws Strike on its last action\nEffect The urdefhan maintains contact, turning the creature's flesh translucent around the site of the injury. The urdefhan chooses one of two options, each of which requires a check (fortitude, dc:32) save. If the jaws Strike was a critical hit, the creature suffers both effects, using the same save result for both.\n• Drain Blood The urdefhan drinks some of the creature's blood. On a failed save, the creature is Drained 1 and the urdefhan regains 5 healing HP (or, on a critical failure, it's Drained 2 and the urdefhan regains 10 healing HP).\n• Drain Vitality (necromancy) The urdefhan draws out some of the creature's vital essence. The creature becomes Enfeebled 1 for 1 hour on a failed save (or Enfeebled 2 for 1 hour on a critical failure).",
          "traits": []
        }
      ],
      "spellcasting": [
        {
          "id": "3pL0yHt4nvMJI7eK",
          "name": "Divine Innate Spells",
          "tradition": "divine",
          "category": "innate",
          "attackModifier": 23,
          "saveDc": 29,
          "spells": [
            {
              "id": "gmbDVefxioirNHej",
              "name": "Feather Fall (At Will) (Self Only)",
              "rank": 3
            },
            {
              "id": "TzoqwLKMXo7eU2Wd",
              "name": "Ray of Enfeeblement",
              "rank": 3
            },
            {
              "id": "xzRl3ICEoX9BktYG",
              "name": "Death Knell",
              "rank": 4
            }
          ]
        }
      ]
    },
