        {
          "id": "GJq1pfArAB262GZd",
          "name": "Raptor Jaw Disarm",
          "kind": "reaction",
          "description": "Frequency once per round\nTrigger A creature makes a melee Strike against the worldwatcher but misses\nEffect The worldwatcher breaks the triggering creature's limb or weapon. If the triggering Strike was an unarmed attack, the triggering creature takes 6d6 bludgeoning damage and becomes Clumsy 1 until the limb is reset (an Interact action with the manipulate trait). If the triggering Strike was a weapon Strike, the weapon takes 6d6 bludgeoning damage.",
          "traits": []
        },
        {
          "id": "pPAfuiRx3hQmyGuJ",
          "name": "Boneshaking Roar",
          "kind": "action",
          "description": "The saurian worldwatcher bellows, evoking the power of the primordial world.\nNon-dinosaur creatures within 30-foot emanation take 10d6 sonic damage (check (fortitude, dc:38, basic, options:area-effect) save). On a failed save, a creature is also Slowed 2 for 1 round (Stunned 1d4 on a critical failure).\nThe saurian can't use Boneshaking Roar again for 1d4.",
          "traits": [
            "incapacitation",
            "sonic"
          ]
        },
        {
          "id": "5utWutqAL3Pfpee3",
          "name": "Stunning Blow",
          "kind": "passive",
          "description": "Whenever the worldwatcher hits a creature with their fist or naginata Strike, that creature must succeed at a check (fortitude, dc:39) save or be Stunned 1 (Stunned 3 on a critical hit).",
          "traits": [
            "incapacitation"
          ]
        }
