    "translatableHash": "sha256:d1efc10353b95bb3b614b5db19b822afecc18b83e9c3a91ffe8d6b51cfa25dc3",
    "data": {
      "schemaVersion": 1,
      "name": "Chalky",
      "level": 9,
      "rarity": "uncommon",
      "size": "large",
      "traits": [
        "alchemical",
        "construct",
        "golem",
        "mindless"
      ],
      "description": "This golem is a walking alchemical nightmare capable of inflicting all manner of painful wounds. Its ability to follow orders is granted by the otherwise mindless humanoid brain that floats in its dome-like head. In exceptionally rare cases, the brain used in its creation might retain fragments of memories or even actual intellect, resulting in an alchemical golem with a personality and agenda of its own.",
      "armorClass": 27,
      "hitPoints": 150,
      "speedFeet": 25,
      "perception": {
        "modifier": 15,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 20,
        "reflex": 19,
        "will": 15
      },
      "abilities": {
        "str": 6,
        "dex": 4,
        "con": 3,
        "int": -5,
        "wis": 0,
        "cha": -5
      },
      "skills": {
        "athletics": 22
      },
      "languages": [],
      "defenses": {
        "immunities": [
          "acid",
          "magic"
        ],
        "resistances": [
          "physical 12 except adamantine, bludgeoning"
        ],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "2TFdxsGPr1xaX73k",
          "name": "Syringe",
          "bonus": 22,
          "damage": "2d10+6 piercing",
          "traits": [
            "magical",
            "reach-10"
          ]
        }
      ],
      "actions": [
        {
          "id": "LYl3vW92ci5HFVXk",
          "name": "Alchemical Chambers",
          "kind": "passive",
          "description": "An alchemical golem's body contains six alchemical chambers filled with different substances. When an alchemical golem ability calls upon a randomly determined alchemical effect, roll 1d6 and consult the following :\n1d6 |\nAlchemical Effect |\n1 |\nElixir of Life (Lesser)\n |\n2 |\nBomber's Eye Elixir (Lesser) |\n3 |\nBravo's Brew (Moderate) |\n4 |\nCat's Eye Elixir |\n5 |\nCheetah's Elixir (Moderate) |\n6 |\nJuggernaut Mutagen (Greater) |",
          "traits": []
        },
        {
          "id": "10AhR44dLRwNyyyT",
          "name": "Alchemical Rupture",
          "kind": "passive",
          "description": "When an alchemical golem takes physical damage from a critical hit or is affected by a Shatter spell, one glass chamber within its body shatters, spewing alchemical liquid in a 5-foot emanation.\nRoll on the alchemical chambers list to determine which one shatters - all creatures within a 5-foot emanation are affected by the elixir in the randomly rolled alchemical chamber, and these creatures may forego their Reflex saves against the effect if they wish.",
          "traits": []
        },
        {
          "id": "8ubCXo0Jx35U5xxc",
          "name": "Golem Antimagic",
          "kind": "passive",
          "description": "Harmed by sonic 5d8 untyped damage, 2d6 untyped damage from areas or persistent damage); healed by acid (area 2d4 healing HP); slowed by cold",
          "traits": []
        },
        {
          "id": "sbYDSGZlPbw5odWZ",
          "name": "Vulnerable to Shatter",
          "kind": "passive",
          "description": "Casting a Shatter spell on an alchemical golem affects the golem normally, but also causes an alchemical rupture.",
          "traits": []
        },
        {
          "id": "LPMvePNhEQEvIeA1",
          "name": "Alchemical Injection",
          "kind": "passive",
          "description": "When an alchemical golem hits a creature with a syringe Strike, roll 1d6 on the alchemical chambers list to determine the additional effect of the attack.\nChalky's alchemical chambers are filled with helpful potions and elixirs rather than harmful substances. When Chalky targets an ally with its syringe Strike, the ally takes no damage and doesn't need to make a save against the rolled effect.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
