      "traits": [
        "magical",
        "mechanical"
      ],
      "description": "A hidden needle delivers a magical poison to anyone trying to open the door.",
      "armorClass": 31,
      "hitPoints": 100,
      "hardness": 25,
      "stealth": {
        "modifier": 27,
        "details": "(expert)"
      },
