    "sourceHash": "sha256:632a7afdfeb6582d8920a3384d2f73b6bc03d84f3b4f33900358ac9d2db9d344",
    "translatableHash": "sha256:ba7c98cc3f41dc46a19115bc42b49296bfbb31557d5084af2a1979537779b459",
    "data": {
      "schemaVersion": 1,
      "name": "Mr. Snips",
      "level": 14,
      "rarity": "uncommon",
      "size": "large",
      "traits": [
        "construct",
        "golem",
        "mindless"
      ],
      "description": "Traditionally crafted into the forms of giant suits of armor or powerful animals, iron golems are products of exquisite artistry and skill. Their articulated joints and sturdy armored bodies require great care and mathematical precision to craft, and regular cleaning and oiling ensure they don't rust over the ages. With proper care, iron golems can remain in good shape for thousands of years, being passed down for generations, as long as they aren't destroyed by meddlesome adventurers. In addition to their incredible strength, iron golems possess a potent toxic breath weapon that is often more than enough to dispatch entire groups of opponents.",
      "armorClass": 36,
      "hitPoints": 210,
      "speedFeet": 20,
      "perception": {
        "modifier": 23,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 28,
        "reflex": 23,
        "will": 24
      },
      "abilities": {
        "str": 8,
        "dex": -1,
        "con": 4,
        "int": -5,
        "wis": 0,
        "cha": -5
      },
      "skills": {
        "athletics": 32
      },
      "languages": [],
      "defenses": {
        "immunities": [
          "fire",
          "magic"
        ],
        "resistances": [
          "physical 15 except adamantine"
        ],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "0vSVpFhBgh2bSdVc",
          "name": "Fist",
          "bonus": 30,
          "damage": "3d10+14 bludgeoning",
          "traits": [
            "magical",
            "reach-10",
            "unarmed"
          ]
        },
        {
          "id": "pjqAB7UZDOSJ8Dvg",
          "name": "Scissors",
          "bonus": 30,
          "damage": "3d10+14 slashing",
          "traits": [
            "agile",
            "magical",
            "reach-10"
          ]
        }
      ],
      "actions": [
        {
          "id": "lYvWF5v5Vah9KWsN",
          "name": "Golem Antimagic",
          "kind": "passive",
          "description": "Harmed by acid (6d10+4 untyped damage, 2d8+4 untyped damage from areas and persistent damage); healed by fire (area 2d8+4 healing HP); slowed by electricity",
          "traits": []
        },
        {
          "id": "aMNM0X0dVvVRdlZT",
          "name": "Vulnerable to Neutralize Poison",
          "kind": "passive",
          "description": "Casting Cleanse Affliction on the golem deactivates its Breath Weapon for 1 minute.",
          "traits": []
        },
        {
          "id": "SJraLZmz7x1C04ki",
          "name": "Vulnerable to Rust",
          "kind": "passive",
          "description": "Magical rusting effects, like a rust monster's antennae, affect the iron golem normally.",
          "traits": []
        },
        {
          "id": "HkUjt1e6CiwdfHoy",
          "name": "Breath Weapon",
          "kind": "action",
          "description": "The iron golem exhales poisonous gas in a 10-foot burst centered on the corner of one of the iron golem's squares.\nThe gas persists for 1 round. Any creature in the area (or that later enters the area) is exposed to the iron golem's poison.\nThe golem can't use its Breath Weapon again for 1d4.",
          "traits": [
            "arcane",
            "poison"
          ]
        },
        {
          "id": "yhVKDXeyQEVchPJW",
          "name": "Dismember",
          "kind": "passive",
          "description": "Whenever Mr. Snips rolls a critical hit with a scissors Strike, in addition to dealing extra damage, the golem has a chance to dismember its victim. The target must roll a check (reflex, dc:39, traits:damaging-effect) save.\nSuccess No additional effect.\nFailure The target takes 2d10 persistent bleed damage.\nCritical Failure As failure, and one of the targets extremities is severed (the effects of this are up to the GM's discretion).",
          "traits": []
        },
        {
          "id": "nhz5F428cTKGkc9v",
          "name": "Inexorable March",
          "kind": "action",
          "description": "The iron golem Strides up to its Speed, pushing back each creature whose space it moves into and damaging them if they try to stop its movement. A creature can attempt to bar the way by succeeding at a check (fortitude, dc:39) save. On a critical success, the resisting creature takes no damage; otherwise, it is damaged as if hit by the golem's fist.",
          "traits": []
        },
        {
          "id": "RSzJjCjwpz8jIS3J",
          "name": "Iron Golem Poison",
          "kind": "passive",
          "description": "Any Drained value from this poison is reduced by 1 every hour.\nSaving Throw check (fortitude, dc:35)\nMaximum Duration 4 rounds\nStage 1 2d6 poison damage and Drained 1 (1 round)\nStage 2 4d6 poison damage and Drained 2 (1 round)\nStage 3 8d6 poison damage and Drained 3 (1 round)",
          "traits": [
            "poison"
          ]
        }
      ],
      "spellcasting": []
    },
