      "actions": [
        {
          "id": "Ba9gUN2kmGTDwJ7v",
          "name": "Bloody Mayhem",
          "kind": "action",
          "description": "Twisted Jack Strides three times. Once per Stride, he can attempt a war razor Strike against a creature in his reach at any point during the Stride; he must make each Strike against a different creature, but he doesn't apply his multiple attack penalty until after making all his Strikes. If any of the Strikes are a critical failure, Bloody Mayhem immediately ends.",
          "traits": []
        },
        {
          "id": "NvOUKM0pOaTFyrWw",
          "name": "Close Cutter",
          "kind": "passive",
          "description": "Whenever Twisted Jack deals slashing damage, the target takes an additional 2d10 persistent bleed damage.",
          "traits": []
        },
        {
          "id": "aV20X0Mp1CqH1tqz",
          "name": "Fan of Daggers",
          "kind": "action",
          "description": "Twisted Jack makes three ranged dagger Strikes, each against a separate target; he ignores the multiple attack penalty until after making all three Strikes. On a critical hit, the target takes 2d10 persistent bleed damage and is Blinded for 1 round.",
          "traits": []
        },
        {
          "id": "aZlGemIJeXm9jJEE",
          "name": "Knife Thrower",
          "kind": "passive",
          "description": "Twisted Jack's ranged dagger Strikes have a range increment of 20 feet instead of 10 feet.",
          "traits": []
        },
        {
          "id": "rUGUrNdhsxVMFs5r",
          "name": "Sneak Attack",
          "kind": "passive",
          "description": "Twisted Jack deals an additional 3d6 precision damage to Off-Guard targets.",
          "traits": []
        }
      ],
      "spellcasting": []
