      "actions": [
        {
          "id": "A6EBzxn9xWiWavNB",
          "name": "Telepathy 100 feet",
          "kind": "passive",
          "description": "",
          "traits": [
            "aura",
            "magical"
          ]
        },
        {
          "id": "TxhGff0LtzQslOci",
          "name": "Easy to Call",
          "kind": "passive",
          "description": "The sahkil is considered 2 levels lower for the purposes of being summoned by rituals (such as Binding Circle), but is always free to attack or leave instead of negotiate unless the primary caster's check is a critical success.",
          "traits": []
        },
        {
          "id": "py2SpejCikEONHQm",
          "name": "Constant Spells",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "Yp5SbrVfKWgUjXKt",
          "name": "+1 Status to All Saves vs. Magic",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "0mlWlB8x9buvEw3g",
          "name": "Swarm Mind",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "XC6rH5AiexqlIUrJ",
          "name": "Crowded Mob",
          "kind": "passive",
          "description": "The penqual is a swarm of Medium figures that can squeeze supernaturally close to other creatures. Though its component creatures are larger than those of a typical swarm, a penqual can nevertheless share the spaces of other creatures.",
          "traits": []
        },
        {
          "id": "KkQu3TqvmvRwh5Gx",
          "name": "Crush of Hundreds",
          "kind": "passive",
          "description": "A creature Frightened by the sahkil's Mask of Terror feels the press of a suffocating crowd.\nThe creature is Slowed 1 and takes a –10-foot penalty to all Speeds for as long as it is frightened.\nEffect: Crush of Hundreds",
          "traits": []
        },
        {
          "id": "EEMf91Mnk5n3dYup",
          "name": "Frantic Grasp",
          "kind": "action",
          "description": "Each enemy in the penqual's space takes 4d12 slashing damage (check (reflex, dc:36, basic) save).",
          "traits": [
            "evil",
            "magical"
          ]
        },
        {
          "id": "DNsLOiJgbt3epj8c",
          "name": "Mob Rush",
          "kind": "action",
          "description": "The penqual Strides twice, ignoring difficult terrain, and then uses Frantic Grasp. If it moves at least 20 feet away from its starting position, the DC of Frantic Grasp increases by 2.",
          "traits": []
        },
        {
          "id": "29naBTIemmuYyMKB",
          "name": "Skip Between",
          "kind": "action",
          "description": "The sahkil can move itself between the Ethereal Plane and the Material Plane, as Ethereal Jaunt, except that this ability has an unlimited duration and can be Dismissed",
          "traits": [
            "divine",
            "teleportation"
          ]
        }
      ],
