    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Kharnas's Lesser Glyph",
      "level": 17,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "magical",
        "trap"
      ],
      "description": "A hidden glyph suddenly lights up and dominates the mind of any creature not bearing the sigil of Kharnas the Angel-Binder.",
      "armorClass": 0,
      "hitPoints": 10,
      "hardness": 0,
      "stealth": {
        "modifier": 33,
        "details": ""
      },
      "disable": "Disable check (thievery, dc:46, name:Destroy Glyph, traits:action:disable-a-device) (legendary) to destroy the glyph, check (arcana, dc:42, name:Divert Glyph's Power) (master) to harmlessly divert the glyph's power, or Dispel Magic (7th rank; counteract DC 38) to counteract the glyph",
      "isComplex": false,
      "routine": "null",
      "reset": "The glyph can affect two creatures before it deactivates for 5 minutes and automatically resets.",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "HGIf9bu9E1RjDKaF",
          "name": "Dominate",
          "kind": "reaction",
          "description": "Trigger A creature who doesn't bear the sigil of Kharnas attempts to open the door\nEffect A surge of the Radiant Spark's latent power courses through the glyph and washes over the triggering creature. If the creature is undead, it takes 10d10 vitality damage. If it's living, it instead regains 10d10 healing Hit Points. It then must succeed at a check (will, dc:40, traits:incapacitation,mental) save or be affected by a 6th-rank Dominate spell.\nThe spell commands the affected creature to attack the nearest creature who doesn't bear the sigil of Kharnas.",
          "traits": [
            "arcane"
          ]
        }
      ]
    },
