    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Blackfinger's Prayer",
      "level": 19,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "magical",
        "trap"
      ],
      "description": "The trapdoor's metal is infused with a deadly toxin that seeps out when the trap is triggered.",
      "armorClass": 40,
      "hitPoints": 150,
      "hardness": 30,
      "stealth": {
        "modifier": 30,
        "details": "(legendary)"
      },
      "disable": "check (thievery, dc:50, name:Gum Up Trapdoor, traits:action:disable-a-device) (legendary) to gum up the trapdoor's porous metal surface, check (crafting, dc:45, name:Render Toxin Inert) (master) to render the toxin inert, or Dispel Magic (9th rank; counteract DC 45) to counteract the trap's magic",
      "isComplex": false,
      "routine": "",
      "reset": "",
      "saves": {
        "fortitude": 38,
        "reflex": 30,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "K2xZ73LiKk2uqR28",
          "name": "Blackfinger's Prayer",
          "kind": "reaction",
          "description": "Trigger A creature opens the door without first whispering the name Blackfingers\nEffect The metal trapdoor emits toxic vapors. Each creature within 30 feet must save against a potent strain of Blackfinger Blight.",
          "traits": [
            "curse",
            "divine"
          ]
        },
        {
          "id": "A04N1HzBOQCcYnM2",
          "name": "Blackfinger Blight",
          "kind": "passive",
          "description": "Each round, at the beginning of their turn, a creature affected by blackfinger blight must succeed at a check (flat, dc:5) check or drop one random item they're holding\nSaving Throw check (fortitude, dc:40)\nOnset 1 round\nMaximum Duration 6 rounds\nStage 1 6d6 poison damage (1 round)\nStage 2 8d6 poison damage (1 round)\nStage 3 10d6 poison damage and Confused (1 round)",
          "traits": [
            "inhaled",
            "poison",
            "virulent"
          ]
        }
      ]
    },
