    "data": {
      "schemaVersion": 1,
      "name": "Living Mural",
      "level": 19,
      "rarity": "rare",
      "size": "huge",
      "traits": [
        "chaotic",
        "construct"
      ],
      "description": "",
      "armorClass": 43,
      "hitPoints": 100,
      "speedFeet": 25,
      "perception": {
        "modifier": 32,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 31,
        "reflex": 34,
        "will": 30
      },
      "abilities": {
        "str": 6,
        "dex": 10,
        "con": 5,
        "int": -2,
        "wis": 2,
        "cha": 1
      },
      "skills": {
        "acrobatics": 38,
        "crafting": 27,
        "deception": 37,
        "stealth": 38
      },
      "languages": [
        "common"
      ],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "aap2jSjnDkxEKZUI",
          "name": "Fist",
          "bonus": 37,
          "damage": "4d8+15 bludgeoning",
          "traits": [
            "agile",
            "finesse",
            "magical",
            "reach-15",
            "unarmed"
          ]
        },
        {
          "id": "HMCS1B66LSvBKspC",
          "name": "Splatter",
          "bonus": 35,
          "damage": "3d8+4 bludgeoning",
          "traits": [
            "magical",
            "nonlethal"
          ]
        }
      ],
      "actions": [
        {
          "id": "EKp5irpqgnTwEyjX",
          "name": "Backdrop",
          "kind": "passive",
          "description": "When a creature attempts to Strike a living mural and critically misses, the attacker hits the surface (a wall, canvas, or so on) behind the living mural. This can damage or break the weapon or surface.",
          "traits": []
        },
        {
          "id": "6BA0nR5VEDa0Aw15",
          "name": "Surface-Bound",
          "kind": "passive",
          "description": "A living mural can move only along flat surfaces such as floors and walls. This allows it to end its movement wrapped around corners when on a continuous surface.\nIf the surface it's on is destroyed (such as a portrait hit by a fireball spell or a puddle being splashed), the mural takes 10d6 untyped damage and is shunted to the nearest flat surface. If there is no flat surface within 5 feet, the living mural is destroyed.",
          "traits": []
        },
        {
          "id": "6gBFZhqoL9eg2XDz",
          "name": "Collective Attack",
          "kind": "action",
          "description": "The subjects depicted within the living mural all reach out at once to attack. The living mural makes a fist Strike against each target within range.\nThese attacks count toward the living mural's multiple attack penalty, but this penalty doesn't increase until after all of the attacks are made.",
          "traits": []
        },
        {
          "id": "YE6DApvJToive72E",
          "name": "Paint the Masses",
          "kind": "action",
          "description": "The living mural expels a 15-foot cone of paint.\nCreatures in the area must succeed at a check (reflex, dc:41) save or be Blinded for 1 round.\nThe living mural can't use Paint the Masses again for 1d4.",
          "traits": []
        },
        {
          "id": "snJ95Lkh1TmrNndQ",
          "name": "Splash of Color",
          "kind": "passive",
          "description": "When the living mural hits with a splatter attack, the target is also Blinded for 1 round.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
