    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Freezing Alarm",
      "level": 20,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "magical",
        "trap"
      ],
      "description": "Miniature snowflake-shaped glyphs on the ground cause a layer of ice to ripple over the floor of the room and sound a silent alarm.",
      "armorClass": 0,
      "hitPoints": 10,
      "hardness": 0,
      "stealth": {
        "modifier": 33,
        "details": "(master)"
      },
      "disable": "check (arcana, dc:53, name:Disable Arcana) (legendary) to draw a fiery counteracting glyph over each snowflake, or Dispel Magic (9th rank, counteract DC 48)",
      "isComplex": false,
      "routine": "",
      "reset": "1 day",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "DdFilDnuHDObT81V",
          "name": "Freeze Floor",
          "kind": "reaction",
          "description": "Trigger A creature enters one of the three squares marked with a T on the map\nEffect The floor of the entire 10-foot-by-15-foot antechamber freezes over, sending deadly magical frost creeping up the legs of the intruders. Any creatures standing in the room must roll a check (reflex, dc:45) save.\nCritical Success The creature is unaffected.\nSuccess The creature takes 3d10+5 cold damage.\nFailure The creature takes 6d10+10 cold damage and is Slowed 1 for 1d4.\nCritical Failure The creature takes 12d10+20 cold damage and is Slowed 1 for 1 minute.\nAdditionally, the golems in area B10 become aware of the intruders. The golems activate and come to this room to attack, if they haven't been destroyed already.",
          "traits": [
            "arcane",
            "cold"
          ]
        }
      ]
    },
